import {BaseEntity} from '../../../shared/domain/model/base-entity';

/**
 * Represents a reservation registered for a sports center.
 *
 * @author José Santana
 */
export class Reservation implements BaseEntity {
  /**
   * Unique identifier of the reservation (generated by the backend).
   */
  #id: number;

  /**
   * Identifier of the sports center associated with the reservation.
   */
  #sportsCenterId: number;

  /**
   * Activity type of the reservation.
   */
  #activityType: string;

  /**
   * Name of the participant responsible for the reservation.
   */
  #participantName: string;

  /**
   * Number of attendees included in the reservation.
   */
  #participants: number;

  /**
   * Temperature registered at the sports center when the reservation was created.
   */
  #weatherTemperature: number;

  /**
   * Date and time when the reservation was created.
   */
  #reservedAt: Date;

  /**
   * Creates a new reservation entity.
   * @param props - Initialization values.
   */
  constructor(props: {
    id: number;
    sportsCenterId: number;
    activityType: string;
    participantName: string;
    participants: number;
    weatherTemperature: number;
    reservedAt: Date;
  }) {
    this.#id = props.id;
    this.#sportsCenterId = props.sportsCenterId;
    this.#activityType = props.activityType;
    this.#participantName = props.participantName;
    this.#participants = props.participants;
    this.#weatherTemperature = props.weatherTemperature;
    this.#reservedAt = props.reservedAt;
  }

  get id(): number {
    return this.#id;
  }

  set id(value: number) {
    this.#id = value;
  }

  get sportsCenterId(): number {
    return this.#sportsCenterId;
  }

  set sportsCenterId(value: number) {
    this.#sportsCenterId = value;
  }

  get activityType(): string {
    return this.#activityType;
  }

  set activityType(value: string) {
    this.#activityType = value;
  }

  get participantName(): string {
    return this.#participantName;
  }

  set participantName(value: string) {
    this.#participantName = value;
  }

  get participants(): number {
    return this.#participants;
  }

  set participants(value: number) {
    this.#participants = value;
  }

  get weatherTemperature(): number {
    return this.#weatherTemperature;
  }

  set weatherTemperature(value: number) {
    this.#weatherTemperature = value;
  }

  get reservedAt(): Date {
    return this.#reservedAt;
  }

  set reservedAt(value: Date) {
    this.#reservedAt = value;
  }
}
